
/* Deterministic teaching interactions. No model is running behind these activities. */
let methodIndex=0,aiismIndex=0;
let pauseClock={remaining:240,running:false,deadline:0};
let graphState={step:-1,selected:0,mode:'missing',resolution:'',evidence:false,updated:false};
function widgetHead(label,title,ico='spark'){return `<div class="widget-head"><div><span class="eyebrow">${label}</span><h3>${title}</h3></div><span class="widget-icon">${icon(ico)}</span></div>`;}
function widgetNote(text){return `<p class="source-note">${text}</p>`;}
const WIDGETS={
 preflight:()=>`<div class="widget">${widgetHead('Worksheet','Consider this particular use of AI','shield')}<p class="widget-intro">Use what you know about the assignment and the actual rules. If an answer is uncertain, the form will help you identify what to resolve; it cannot give you permission to proceed.</p>${field('preflight-task','Which task are you considering?','Describe a fictional or non-sensitive assignment in a sentence.')}
 <div class="form-grid">${selectField('preflight-permission','1. Is this use permitted?',[['','Choose an answer'],['yes','Yes, I have checked the relevant requirements'],['no','No'],['unknown','I have not established that yet']])}${selectField('preflight-data','2. Is this system approved for the information?',[['','Choose an answer'],['yes','Yes, this data and use are approved'],['no','No, or the material is sensitive and not approved'],['unknown','Access, retention, or approval is unclear']])}${selectField('preflight-stakes','3. What could happen if the result is wrong?',[['','Choose an answer'],['low','The effect is minor and readily reversible'],['high','It could affect a client, right, deadline, or formal work'],['unknown','I do not yet understand the consequences']])}${selectField('preflight-verify','4. Can you identify how to check the result?',[['','Choose an answer'],['yes','Yes, I can name a suitable source, test, or reviewer'],['no','Not yet']])}${selectField('preflight-first','5. Have you done the initial thinking this task needs?',[['','Choose an answer'],['yes','Yes, I have an attempt or view to compare'],['no','Not yet'],['na','This is a mechanical task I can already assess']])}</div><div id="preflight-result" class="status-box" aria-live="polite"></div>${field('preflight-plan','What do you need to do next?','Name the requirement to resolve or the check to arrange. A general promise to be careful does not identify the action.')}${widgetNote('The before-use questions come from Joe Regalia’s responsible-use teaching. The explanation follows your selections; it does not approve the use.')}</div>`,
 pause:()=>`<div class="widget">${widgetHead('Self-assessment worksheet','Write your own assessment before feedback','clock')}<p class="widget-intro">The timer is optional and does not close the form. Your answers save as you type; the button after the questions keeps a separate copy for comparison.</p><div class="timer"><div class="timer-digits" id="pause-digits" aria-label="Time remaining">${clockText()}</div><span class="small muted">Optional<br>four-minute timer</span><div class="actions"><button class="button compact" data-action="timer-toggle">${icon(pauseClock.running?'pause':'play')} ${pauseClock.running?'Pause timer':'Start timer'}</button><button class="text-btn" data-action="timer-reset">Reset timer</button></div></div>${['What is my current answer?','What is the strongest part of my reasoning?','What is the weakest part?','What authority or fact still needs checking?','What feedback would most help me?'].map((q,i)=>field(`pause-${i}`,q,['State your current conclusion and its basis.','Identify something your reasoning already explains well.','Name the part you are least sure you can defend.','Identify the source or factual question that needs another look.','Ask for the kind of feedback that would help you improve the attempt.'][i])).join('')}<button class="button primary compact" data-action="pause-save">${icon('note')} ${value('pause-baseline')?'Replace the saved comparison copy':'Save assessment for comparison'}</button>${value('pause-baseline')?`<details class="disclosure"><summary>Read the assessment saved for comparison</summary><div class="inside"><p style="white-space:pre-wrap">${esc(value('pause-baseline'))}</p></div></details><div class="rule"></div><h4>After you receive feedback elsewhere</h4><p class="widget-intro">Use one important suggestion from a permitted tool, a colleague or classmate, or a later review. Compare it with the saved assessment rather than changing your first view to match it.</p>${field('pause-feedback','What suggestion did you receive?','Describe the suggestion without entering confidential information.')}${selectField('pause-decision','What will you do with that suggestion?',[['','Choose after comparing'],['Accept','Accept it'],['Modify','Modify it'],['Reject','Reject it']])}${field('pause-reason','Why is that the right choice?','Explain the source support, reasoning, or practical consideration behind your decision.')}`:`<p class="small muted" style="margin-top:14px">Answer all five questions, then save the comparison copy to open the follow-up questions. This page does not generate feedback.</p>`}${widgetNote('This is a suggested self-assessment practice. Four minutes is not an established threshold for legal performance. See the source notes for the limits of the classroom research.')}</div>`,
 method:()=>`<div class="widget">${widgetHead('Six collaboration practices','Choose a practice to see how it works','layers')}<p class="widget-intro">These practices can be combined as the assignment requires. Selecting one opens an explanation and an instruction to adapt; it does not send a request to AI.</p><div class="method-steps">${METHOD.map((m,i)=>`<button class="method-step" data-action="method-step" data-step="${i}" aria-pressed="${methodIndex===i}"><span class="mono">${num(i+1)}</span><span>${m[0]}</span></button>`).join('')}</div><div class="method-detail" aria-live="polite"><h4>${METHOD[methodIndex][1]}</h4><p>${METHOD[methodIndex][2]}</p><div class="prompt-box"><div class="prompt-top"><span>An instruction to adapt</span><button class="text-btn" data-copy-parent=".prompt-box">Copy instructions ${icon('copy')}</button></div><pre>${METHOD[methodIndex][3]}</pre></div></div>${widgetNote('These collaboration practices help with individual exchanges. The five-stage responsible-use process covers the broader assignment; the related chapter explains the difference.')}</div>`,
 promptbuilder:()=>`<div class="widget">${widgetHead('Prompt builder','Describe the assignment you want to give','list')}<p class="widget-intro">Start with your own task or load an example. Loading an example fills this form and asks before replacing existing entries; it does not create another project.</p><div class="actions preset-options"><button class="button compact" data-action="prompt-preset" data-preset="heading">Load a heading example</button><button class="button compact" data-action="prompt-preset" data-preset="sources">Load a source-comparison example</button><button class="button compact" data-action="prompt-preset" data-preset="tutor">Load a tutoring example</button></div><div class="form-grid">${field('prompt-task','What should the AI help you do?','Define one task you can review, such as comparing specified provisions or examining your argument.',{full:true})}${field('prompt-goal','Who is the work for, and what do they need?','Describe the reader and the decision or result the work should support.')}${field('prompt-first','What have you already worked out?','Describe your reading, initial conclusion, or attempt so the tool knows what it is responding to.')}${field('prompt-sources','Which materials may it use?','Identify the documents and versions. Supply them in the approved AI tool when you use the prompt.')}${field('prompt-boundaries','What must remain unchanged or out of bounds?','Identify important qualifications and any limits on sources or actions.')}${field('prompt-output','What should it return to you?','Specify the form and amount of work you can review, such as a table before a recommendation.')}${field('prompt-example','What example would help explain your standard?','Describe or supply an appropriate example and explain the feature you want the tool to learn.')}${field('prompt-check','What must be checked or brought back to you?','Describe the support required and any missing information or decision that should stop the work.',{full:true})}</div><div class="prompt-box"><div class="prompt-top"><span>Your assembled instructions</span><button class="text-btn" data-copy-parent=".prompt-box">Copy instructions ${icon('copy')}</button></div><pre id="prompt-output-text"></pre></div><p class="small muted">Read these instructions before using them. Replace any remaining bracketed text and supply the permitted materials in the other tool.</p><div class="actions"><button class="button primary compact" data-action="save-built-prompt">${icon('note')} Save this version</button><button class="button compact" data-action="download-built-prompt">${icon('download')} Download prompt</button></div>${widgetNote('The form assembles text; it does not run AI or evaluate the prompt. Current fields save automatically, and “Save this version” keeps a separate copy.')}</div>`,
 graph:()=>renderGraph(),
 workorder:()=>`<div class="widget">${widgetHead('Agent assignment worksheet','Specify the work and the limits on it','list')}<p class="widget-intro">Use the question-mark buttons for examples of the twelve assignment fields. Your answers prepare instructions; permissions must be configured in the application that will perform the work.</p><button class="button compact" data-action="order-preset" style="margin-bottom:24px">Load the fictional vendor example ${icon('arrow')}</button>${[
 ['The assignment',['outcome','scope','deliverable']],['Sources and standards',['inputs','tools','quality','evidence']],['Limits and review',['prohibited','stop','approval']],['Testing and records',['tests','record']]
 ].map(([heading,keys])=>`<fieldset class="form-section"><legend>${heading}</legend><div class="form-grid">${keys.map(key=>{const row=ORDER_FIELDS.find(x=>x[0]===key);return field(`order-${key}`,row[1],row[2]);}).join('')}</div></fieldset>`).join('')}<details class="disclosure"><summary>Read the complete work order</summary><div class="inside"><pre id="order-output-text"></pre></div></details><div class="actions"><button class="button primary compact" data-action="copy-order">${icon('copy')} Copy work order</button><button class="button compact" data-action="download-order">${icon('download')} Download work order</button></div>${widgetNote('This form prepares an assignment. It does not launch an agent or implement approval controls. The vendor preset is a fictional example.')}</div>`,
 fee:()=>{const pick=Number(value('fee-choice')),has=['0','1','2'].includes(String(value('fee-choice'))),open=value('fee-open')===true||has;return `<div class="widget">${widgetHead('Sentence-revision exercise','Compare style changes with changes in meaning','pen')}<span class="sample-label">Supplied sentence · Skills & AI-isms, slide 20</span><div class="original-passage">${FEE_ORIGINAL}</div>${field('fee-draft','Your first revision','Rewrite the sentence, or describe what you would change. Keep track of what it tells investors about direct and indirect costs.')}<button class="button primary compact" data-action="fee-open">${open?'Comparison versions are open':'Open the comparison versions'}</button>${open?`<p class="widget-intro" style="margin-top:24px">Select each alternative to examine the response to a different instruction. The explanations are prepared discussion, not feedback on the sentence you wrote.</p><div class="tab-row">${FEE_OPTIONS.map((o,i)=>`<button class="tab" data-action="fee-option" data-step="${i}" aria-pressed="${has&&pick===i}">${o.label}</button>`).join('')}</div><div aria-live="polite">${has?`<div class="original-passage">${FEE_OPTIONS[pick].text}</div><div class="comparison-note">${FEE_OPTIONS[pick].note}</div>`:`<div class="status-box"><p>Choose an alternative to read its explanation, then compare the other versions.</p></div>`}</div>${field('fee-reflection','Which version would you use, and why?','Explain a change that helps the reader and identify any substantive distinction that must remain.')}`:''}${widgetNote('The original and comparison versions come from Skills & AI-isms, slides 20–24. The discussion was written for this guide. A shorter sentence is not automatically the best revision.')}</div>`;},
 stonebridge:()=>renderCase('stonebridge',STONEBRIDGE,'Make the obstacle to confirmation clear'),
 falcon:()=>renderCase('falcon',FALCON,'Explain what needs to be resolved before disclosure'),
 aiisms:()=>`<div class="widget">${widgetHead('Editing exercise','Examine what the language does for the reader','scan')}<p class="widget-intro">Read the deliberately weak source passage. Choose a category to see prepared annotations, then explain what you would address. The categories do not identify who wrote the text.</p><div class="tab-row">${AIISM_LENSES.map((l,i)=>`<button class="tab" data-action="aiism-lens" data-step="${i}" aria-pressed="${aiismIndex===i}">${l.name}</button>`).join('')}</div><span class="sample-label">Supplied passage for editing</span><div class="original-passage" id="aiism-passage">${annotatePassage(AIISM_TEXT,AIISM_LENSES[aiismIndex].phrases)}</div><div class="comparison-note" aria-live="polite"><strong>${AIISM_LENSES[aiismIndex].name}</strong><p>${AIISM_LENSES[aiismIndex].explain}</p></div>${field('aiisms-note','What would you address first?','Explain a writing problem and a gap in the substance. Identify what you would need to know rather than inventing a fact or authority.')}${widgetNote('Passage: Skills & AI-isms, slides 67 and 72. Categories: slides 61–65. The annotations were written for this guide; this is not an AI detector.')}</div>`,
 process:()=>`<div class="widget">${widgetHead('Process-improvement worksheet','Describe the current work before proposing a change','flow')}<p class="widget-intro">Use a familiar service you can describe without sensitive information. The sequence below the form repeats your listed steps; it does not create an automated workflow.</p><div class="form-grid">${field('process-outcome','1. What result does the client need?','Describe a practical outcome rather than naming only a document.',{full:true})}${field('process-steps','2. How does the work happen now?','Write one current step per line. Include who performs it and what passes to the next person.',{full:true,large:true})}${field('process-friction','3. Where does the process cause difficulty?','Describe waiting, repeated work, missing information, or an unclear responsibility that affects the result.')}${field('process-remove','4. What could you remove or clarify?','Explain the value a step protects before deciding whether it is unnecessary.')}${field('process-actor','5. Who or what should perform the work?','Identify where a lawyer is needed and where a client, staff member, ordinary software, or AI could contribute.')}${field('process-controls','6. How will the important risks be controlled?','Specify the review or restriction needed at the step where an error could matter.')}${field('process-pilot','7. What limited change could you test?','Choose a low-risk part and identify the people and examples that would reveal whether it helps.')}${field('process-measure','8. How will you judge the overall result?','Include the effect on quality and the user’s experience, taking review and rework into account.')}${field('process-version','9. Who will review and update the proposal?','Identify the owner, what needs to be retained, and which tests should be repeated after a change.',{full:true})}</div><h4>The current sequence you entered</h4><div id="process-map" class="process-map"></div><div class="actions"><button class="button primary compact" data-action="copy-process">${icon('copy')} Copy process brief</button><button class="button compact" data-action="download-process">${icon('download')} Download process brief</button></div>${widgetNote('The form records your proposed process and repeats the sequence you enter. The proposal still needs appropriate review and testing.')}</div>`,
 shipping:()=>`<div class="widget">${widgetHead('Prototype-review worksheet','Record the evidence a reviewer would need','shield')}<p class="widget-intro">Write the evidence or outstanding work for each area. Check the box only when you consider it addressed. The summary reports your entries, not an independent assessment.</p>${SHIPPING.map(([t,h],i)=>`<fieldset class="review-area"><legend>Review area ${i+1}</legend>${checkField(`shipping-${i}`,t,h)}${field(`shipping-evidence-${i}`,'What evidence supports this, or what remains to be done?','Identify the relevant test, source, or reviewer and explain what was established. An unchecked area can still have a useful note about work that remains.')}</fieldset>`).join('')}<div id="shipping-result" class="status-box" aria-live="polite"></div>${widgetNote('The six areas organize your review. Completing this worksheet is not a legal, security, or deployment certification.')}</div>`,
 playbook:()=>`<div class="widget">${widgetHead('Personal playbook worksheet','Turn a useful experience into a lesson you can reuse','note')}<p class="widget-intro">Begin with an area where you have a concrete example. These fields help you develop lessons from your saved entries; they do not automatically summarize those entries.</p>${PLAYBOOK_FIELDS.map(([key,title,hint])=>field(`playbook-${key}`,title,hint)).join('')}<div class="actions"><button class="button primary compact" data-action="export-playbook">${icon('download')} Download playbook</button><a href="#/notebook" class="text-btn">Review My saved work ${icon('arrow')}</a></div>${widgetNote('Entries save in this browser. Download a backup from My saved work to restore them elsewhere.')}</div>`,
 reflection:()=>`<div class="widget">${widgetHead('Continuing reflection','Choose a question to revisit','book')}<p class="widget-intro">Write your current view, then return after relevant experience. Each question has separate saved answers; changing the selection does not erase an earlier response.</p><label class="field"><span>Which question would you like to consider?</span><select data-save="reflection-select" id="reflection-select">${REFLECTIONS.map((g,gi)=>`<optgroup label="${esc(g.group)}">${g.questions.map((q,qi)=>`<option value="${gi}-${qi}" ${String(value('reflection-select')||'0-0')===`${gi}-${qi}`?'selected':''}>${esc(q)}</option>`).join('')}</optgroup>`).join('')}</select></label><div id="reflection-fields">${reflectionFields()}</div>${widgetNote('These questions are adapted from Joe Regalia’s teaching materials. They invite reflection and discussion; they do not have an answer key.')}</div>`,
 priorities:()=>`<div class="widget">${widgetHead('Factual-priorities exercise','Decide which questions you would investigate first','person')}<p class="widget-intro">Read the supplied facts before selecting priorities. No controlling law is provided, so this exercise asks you to identify questions rather than decide whether an injunction should issue.</p><details class="disclosure" open><summary>Read the employee-departure facts</summary><div class="inside"><p class="source-facts">${esc(PRIORITY_FACTS)}</p></div></details><p class="widget-intro">Select two or three questions you would start with and explain why. The number is a suggestion, not a scoring rule.</p>${PRIORITY_OPTIONS.map(([t,d],i)=>checkField(`priority-${i}`,t,d)).join('')}${field('priorities-reason','Why would you begin with those questions?','Explain how the client’s objective and available evidence affect your priorities. Identify information that could change the order.')}<div class="actions"><button class="button primary compact" data-action="priorities-reveal">${value('priorities-reveal')===true?'Discussion is open':'Read other ways to approach the facts'} ${icon('arrow')}</button></div>${value('priorities-reveal')===true?`<div class="comparison-note"><h4>Compare the reasons for choosing a priority</h4><p>A lawyer concerned about the strength of the evidence might begin with the shared credentials and the absence of customer declarations. A lawyer considering immediate relief might start with the delay before filing and the breadth of the requested restraint. The customer-initiated-contact exception could be central to an analysis focused on the agreement.</p><p>Those approaches direct attention to different work. Each would still need the relevant law and a clearer account of the client’s objective. Consider which approach changes your view and why; the point is not that every ranking is equally strong.</p></div>${field('priorities-second','How would you revise your priorities?','Explain what changed or stayed the same. Add a question that neither your first list nor the discussion supplied.')}`:''}${widgetNote('Facts from Skills & AI-isms, slide 12. The choices and discussion were written for this platform. The source does not provide a single correct ranking or establish a legal outcome.')}</div>`
};

function fillWidget(el){const id=el.dataset.widget,render=WIDGETS[id];if(!render)return;const l=LABS.find(l=>l.id===id);el.innerHTML=(currentRoute.type==='read'&&l?`<div class="inline-resource-bar"><span>${resourceType(id)} · Same saved response on both pages</span><a href="#/lab/${id}" class="text-btn">Open on its own ${icon('arrow')}</a>${helpButton(id,'Instructions for '+l.title,true)}</div>`:'')+render();}
function hydrateWidgets(){document.querySelectorAll('[data-widget]').forEach(fillWidget);refreshDerived();}
function refreshWidget(id,focusAction){document.querySelectorAll(`[data-widget="${id}"]`).forEach(fillWidget);restoreFields();refreshDerived();if(focusAction)document.querySelector(`[data-widget="${id}"] [data-action="${focusAction}"]:not(:disabled)`)?.focus({preventScroll:true});}
function refreshDerived(){updatePreflight();updatePrompt();updateOrder();updateProcess();updateShipping();updateClockDisplay();}
function updatePreflight(){const el=document.getElementById('preflight-result');if(!el)return;const keys=['permission','data','stakes','verify','first'];const v=Object.fromEntries(keys.map(k=>[k,String(value(`preflight-${k}`))]));let kind='',title='Answer the five questions to identify your next step.',body='The explanation will reflect your selections. You still need the actual permission and a suitable way to review the proposed work.';
 if(keys.every(k=>v[k])){
  if(v.permission!=='yes'||v.data!=='yes'||v.verify!=='yes'){kind='stop';title='Resolve these questions before proceeding.';body=[v.permission!=='yes'?'Establish that the particular use is allowed.':'',v.data!=='yes'?'Do not enter the material until the data and system are authorized.':'',v.verify!=='yes'?'Name a reliable independent source, test, or reviewer before relying on the result.':''].filter(Boolean).join(' ');}
  else if(v.stakes!=='low'||v.first==='no'){kind='warn';title='Decide how the work will be reviewed before you proceed.';body=`${v.first==='no'?'Do the first thinking this task needs. ':''}${v.stakes!=='low'?'The consequences call for specific source checks, review points, and a human decision. ':''}Permission to use the tool does not resolve the consequences of an error in this assignment.`;}
  else{title='Your answers describe a lower-risk use that still needs review.';body='Your answers indicate that permission and the information to use have been addressed, and that you know how to assess the result. Keep the task within those limits and review the finished work. The form does not independently confirm your answers.';}
 }
 el.className=`status-box ${kind}`;el.innerHTML=`<strong>${title}</strong><p>${body}</p>`;
}
function clockText(){const seconds=pauseClock.running?Math.max(0,Math.ceil((pauseClock.deadline-Date.now())/1000)):pauseClock.remaining;return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function updateClockDisplay(){const d=document.getElementById('pause-digits');if(d)d.textContent=clockText();}
setInterval(()=>{if(pauseClock.running&&Date.now()>=pauseClock.deadline){pauseClock.running=false;pauseClock.remaining=0;if(document.querySelector('[data-widget=pause]')){refreshWidget('pause');toast('Four minutes are up. Finish your own assessment before comparing.');}}updateClockDisplay();},500);
const PROMPT_KEYS=['task','goal','first','sources','boundaries','output','example','check'];
const PROMPT_TITLES=['The task','The reader and purpose','My initial work','Permitted sources','Limits on the work','What to return','Example and standard','Checks and decisions'];
function builtPrompt(){return PROMPT_KEYS.map((k,i)=>`${PROMPT_TITLES[i].toUpperCase()}\n${String(value(`prompt-${k}`)).trim()||`[Specify ${PROMPT_TITLES[i].toLowerCase()}.]`}`).join('\n\n')+'\n\nWork only within this assignment. Identify missing inputs or conflicting instructions before making assumptions. Distinguish what the supplied sources establish from an inference you draw. I will review important decisions before relying on the work.';}
function updatePrompt(){const p=document.getElementById('prompt-output-text');if(p)p.textContent=builtPrompt();}
const PROMPT_PRESETS={
 heading:{task:'Offer four genuinely different versions of one argument heading.',goal:'A judge who needs to understand the factual reason for the requested result.',first:'I have identified the governing rule and the factual proposition. I will supply them below.',sources:'Only my supplied proposition, facts, and approved source language.',boundaries:'Do not add facts, authorities, or certainty. Preserve every meaningful qualification.',output:'Four full-sentence headings. For each, explain the emphasis and any substantive risk.',example:'Use a specific actor and action, rather than an abstract topic label. I will supply one heading and explain why it works.',check:'Flag any version that changes the scope of the argument. Wait for me to select or combine approaches.'},
 sources:{task:'Compare approved contract requirements against a separate approved factual timeline.',goal:'An internal lawyer decision about what is supported and what needs investigation before advice.',first:'I reviewed the source packet and identified the provisions and factual questions below.',sources:'The signed agreement, supplied amendment, correspondence, service records, and lawyer-supplied governing-law analysis.',boundaries:'Do not infer receipt from proof of sending. Do not resolve source conflicts silently. No external action.',output:'A table: requirement; supporting evidence; contrary or missing evidence; source location; unresolved question.',example:'Label the difference between “sent on June 4” and “received on June 4.” Do not treat either example date as a fact in the actual task.',check:'Flag unreadable or missing material. Stop before drafting a recommendation. I will inspect sources and decide the next step.'},
 tutor:{task:'Help me test my own analysis through questions.',goal:'A lawyer or law student practicing how to interpret sources and apply a rule.',first:'I have read the assigned materials and written my own answer. My answer appears below.',sources:'Only the assignment’s permitted materials and my initial response.',boundaries:'Do not write a replacement answer or assume that I have permission to use AI beyond this activity.',output:'One question at a time, followed by feedback after I respond.',example:'Point me to the source passage I should reread rather than immediately supplying the proposition.',check:'Distinguish source-supported observations from inferences. Ask me to defend a material conclusion before suggesting a revision.'}
};
function orderText(){return 'AGENT WORK ORDER\n\n'+ORDER_FIELDS.map(([k,t,h])=>`${t.toUpperCase()}\n${String(value(`order-${k}`)).trim()||`[${h}]`}`).join('\n\n');}
function updateOrder(){const p=document.getElementById('order-output-text');if(p)p.textContent=orderText();}
function renderCase(id,data,title){const open=value(`${id}-revealed`)===true;return `<div class="widget">${widgetHead('Writing exercise',title,'pen')}<p class="widget-intro">Make your own revision before reading the example. You may instead describe your proposed changes if you are not ready to draft. The comparison should help you examine your decisions; it does not grade your writing.</p><details class="disclosure" open><summary>Read the supplied passage</summary><div class="inside"><p class="original-passage" style="margin:0">${data.original}</p></div></details>${field(`${id}-draft`,'Your first revision','Rewrite the paragraph or explain the changes you would make. Preserve the material facts and conditions.',{large:true})}<button class="button primary compact" data-action="reveal-case" data-case="${id}">${icon('eye')} ${open?'Comparison revision is open':'Read the comparison revision'}</button>${open?`<div class="rule"></div><span class="eyebrow">Comparison written for this guide</span><div class="prompt-box case-sample"><div class="prompt-top"><span>One possible revision</span><button class="text-btn" data-copy-parent=".case-sample">Copy example ${icon('copy')}</button></div><pre>${esc(data.revision)}</pre></div><h4 style="margin:24px 0 12px">Check both versions against the source</h4><p class="widget-intro">Use these points to review what your revision and the example preserve. Checking a box records your review; it is not an automated check.</p>${data.checks.map((c,i)=>checkField(`${id}-check-${i}`,c)).join('')}${field(`${id}-lesson`,'What would you keep or change?','Explain which approach better serves this reader and identify any change you would make to the example.')}`:''}${widgetNote(data.source)}</div>`;}
function annotatePassage(text,phrases){if(!phrases.length)return esc(text);const reg=new RegExp('('+[...phrases].sort((a,b)=>b.length-a.length).map(p=>p.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','gi');return text.split(reg).map(p=>phrases.some(x=>x.toLowerCase()===p.toLowerCase())?`<mark>${esc(p)}</mark>`:esc(p)).join('');}
const GRAPH_NODES = [
  {
    "title": "Define the assignment",
    "actor": "Human decision",
    "inputs": "The client’s objective, approved materials, and relevant governing-law analysis.",
    "output": "A question and proposed result that the lawyer has reviewed.",
    "check": "Confirm that the task serves the client’s need and is permitted.",
    "stop": "Pause if the purpose, permitted information, or basis for review is unclear."
  },
  {
    "title": "Review the contract",
    "actor": "AI assistance; lawyer review",
    "inputs": "The signed agreement, amendment, and approved question.",
    "output": "A table identifying the relevant requirements, with source language and qualifications.",
    "check": "Read the provisions together and keep extraction separate from deciding whether they are satisfied.",
    "stop": "Report missing referenced documents or a conflict that needs the lawyer’s interpretation."
  },
  {
    "title": "Prepare the factual timeline",
    "actor": "AI assistance; lawyer review",
    "inputs": "The approved correspondence and service records.",
    "output": "A timeline with a source location for each material entry and unresolved facts identified.",
    "check": "Distinguish evidence of sending from evidence of receipt. Preserve allegations and conflicting accounts as such.",
    "stop": "Report a material date or event that the record does not establish."
  },
  {
    "title": "Compare the requirements and facts",
    "actor": "AI assistance; lawyer review",
    "inputs": "The two reviewed tables and the underlying documents.",
    "output": "A comparison explaining what is supported and what still needs to be established.",
    "check": "Retain contrary evidence and identify missing facts that could change the conclusion.",
    "stop": "Do not infer that the cure period expired when the record does not establish receipt."
  },
  {
    "title": "Decide how to proceed",
    "actor": "Human approval",
    "inputs": "The comparison, unresolved questions, and the client’s priorities.",
    "output": "Instructions stating the approved approach and any qualification the draft must preserve.",
    "check": "Decide what further investigation is needed and whether a qualified draft would be useful.",
    "stop": "Wait for the lawyer’s decision rather than letting the drafting task settle the uncertainty."
  },
  {
    "title": "Prepare the recommendation",
    "actor": "AI assistance",
    "inputs": "The reviewed findings and the lawyer’s instructions, including the supplied legal analysis.",
    "output": "A draft that explains the approved recommendation and its limits.",
    "check": "Preserve the qualifications and do not add facts or authorities.",
    "stop": "Ask the lawyer if a requested conclusion would go beyond the approved material."
  },
  {
    "title": "Compare the draft with its sources",
    "actor": "Source comparison and lawyer review",
    "inputs": "The draft, original sources, and instructions.",
    "output": "Identified discrepancies and questions the reviewer could not resolve.",
    "check": "Examine the underlying material rather than treating another AI answer as verification.",
    "stop": "Return an unsupported material assertion for correction or a decision."
  },
  {
    "title": "Approve the result for its intended use",
    "actor": "Human approval",
    "inputs": "The reviewed draft and the record of resolved or expressly preserved questions.",
    "output": "A result the lawyer can explain and appropriately rely on.",
    "check": "Confirm the recommendation still fits the client’s needs and that important choices are supported.",
    "stop": "Do not proceed with an unresolved material issue or an external action lacking approval."
  }
];
function graphStatus(){const g=graphState;if(g.step<0)return ['The example is ready to begin.','Begin by assuming the lawyer has defined the client’s question and approved the materials, including the relevant legal analysis. The next step will separate the contract review from the factual timeline.',''];if(g.step===0)return ['The question and boundaries are set.','Next, review the contract and construct the factual timeline as separate tasks. They share the approved question but have different jobs.',''];if(g.step===2&&g.updated)return ['The new evidence requires another look at the later work.','In this prepared variation, assume the lawyer has reviewed new evidence establishing receipt. The example returns to the timeline so the comparison and recommendation can be reconsidered. The contract review may remain useful, subject to checking for newly relevant provisions.','warn'];if(g.step===2)return ['The initial reviews are ready to compare.','The contract ties the cure period to receipt. The timeline must preserve what the records actually establish. Bring both findings and their sources into the comparison.',''];if(g.step===3&&!g.evidence&&g.mode==='missing'&&!g.resolution)return ['Stop: sending is not proof of receipt.','The packet establishes that notice was sent, but it does not establish receipt. The workflow cannot silently treat the cure period as expired. Choose a human response to this gap.','warn'];if(g.step===3)return ['The comparison needs a human decision.',g.resolution==='qualified'?'You chose to preserve the missing receipt evidence and expressly qualify the draft. Approve that limited approach before drafting.':'For this scenario, receipt is established by lawyer-reviewed evidence. That resolves one factual gap; it does not determine every condition for termination. Approve the next step after reviewing the comparison.',''];if(g.step===4)return ['The lawyer has selected an approach.','Only the approved findings, qualifications, and instructions should move into the drafting task. The tool does not get to choose a different recommendation silently.',''];if(g.step===5)return ['A draft is ready for checking.',g.resolution==='qualified'?'The training draft says: “The current packet does not establish when notice was received. Confirm receipt and the remaining contractual conditions before deciding whether termination is available.”':'The training draft retains the established receipt evidence and identifies the remaining contractual and legal questions. A resolved date is not a blanket conclusion that termination is permitted.',''];if(g.step===6)return ['The example has reached the source-review step.','This prepared step illustrates comparing the draft with the underlying material and the lawyer’s instructions. In actual work, you would perform or review those checks and resolve important discrepancies before approval. The simulation has not verified a document.',''];return ['You have reached the end of the example.','The example has moved from the initial assignment through review and approval. Nothing was sent or filed. Record what the missing evidence changed; you can also restart the example with a different response to the gap.',''];}
function graphNextLabel(){const s=graphState.step;if(s<0)return 'Begin the example';if(s===0)return 'Review the two initial results';if(s===2)return 'Compare the findings';if(s===3)return 'Approve this approach before drafting';if(s===4)return 'Read the example draft';if(s===5)return 'Continue to the source-review step';if(s===6)return 'Approve the example result';return 'Example complete';}
function renderGraph(){
 const g=graphState,[title,body,kind]=graphStatus(),blocked=g.step===3&&g.mode==='missing'&&!g.evidence&&!g.resolution,selected=GRAPH_NODES[g.selected];
 const node=i=>{const n=GRAPH_NODES[i],done=g.step>=i;return `<button class="graph-node ${n.actor.startsWith('Human')?'human':''} ${done?'finished':''} ${blocked&&i===3?'blocked':''} ${g.updated&&i>=2?'updated':''}" data-action="graph-node" data-step="${i}" aria-pressed="${g.selected===i}"><span class="node-num">${num(i+1)}</span><span class="node-content">${n.title}<small>${n.actor}</small></span>${icon(blocked&&i===3?'info':done?'check':n.actor.startsWith('Human')?'person':'list')}</button>`;};
 return `<div class="widget graph-widget">${widgetHead('Prepared workflow example','Reviewing a software-vendor matter','flow')}<p class="widget-intro">The client wants to assess termination after service failures. Assume the lawyer has supplied the governing-law analysis and approved the materials. The contract measures a cure period from receipt of written notice, but the initial packet establishes only that notice was sent.</p><details class="disclosure"><summary>How the diagram and walkthrough work</summary><div class="inside"><p>Click any task to read its instructions in the task panel. This changes what you are inspecting but does not complete that task. The main button in the walkthrough explanation advances the prepared example.</p><p>When receipt evidence is missing, choose whether to introduce the supplied evidence variation or preserve the uncertainty in a qualified draft. Either choice still requires the separate approval step before drafting.</p></div></details><div class="tab-row" aria-label="Choose the example’s starting evidence"><button class="tab" data-action="graph-mode" data-mode="missing" aria-pressed="${g.mode==='missing'}">Start with receipt evidence missing</button><button class="tab" data-action="graph-mode" data-mode="complete" aria-pressed="${g.mode==='complete'}">Start with receipt evidence supplied</button></div><section class="walkthrough-panel"><span class="eyebrow">Walkthrough ${g.step<0?'· Ready to begin':g.step===7?'· Complete':'· In progress'}</span><div class="status-box graph-status ${kind}" aria-live="polite"><strong>${title}</strong><p>${body}</p></div><div class="actions graph-controls"><button class="button primary compact" data-action="graph-next" ${blocked||g.step===7?'disabled':''}>${graphNextLabel()} ${icon('arrow')}</button><button class="text-btn" data-action="graph-reset">${icon('reset')} Restart this example</button></div>${blocked?`<div class="missing-decision"><h4>Choose how to handle the missing evidence</h4><p>The disabled button cannot proceed until you make a choice. Adding the evidence returns the work to the timeline; preserving the gap prepares the approach for your separate approval.</p><div class="actions"><button class="button compact" data-action="graph-evidence">Use the supplied receipt-evidence variation</button><button class="button compact" data-action="graph-qualify">Keep the uncertainty in the proposed draft</button></div></div>`:''}${g.step===7&&!g.updated?`<button class="button compact" data-action="graph-evidence">Introduce new receipt evidence ${icon('flow')}</button>`:''}</section><div class="graph-workspace"><div><h4 class="graph-pane-title">Select a task to inspect</h4><div class="graph-canvas">${node(0)}<div class="graph-arrow" aria-hidden="true">↓</div><div class="graph-pair">${node(1)}${node(2)}</div><div class="graph-arrow" aria-hidden="true">↓</div>${node(3)}<div class="graph-arrow" aria-hidden="true">↓</div>${node(4)}<div class="graph-arrow" aria-hidden="true">↓</div>${node(5)}<div class="graph-arrow" aria-hidden="true">↓</div>${node(6)}<div class="graph-arrow" aria-hidden="true">↓</div>${node(7)}</div></div><aside class="graph-detail" aria-live="polite" tabindex="-1"><button class="text-btn graph-back" data-action="graph-back">← Back to the task diagram</button><span class="eyebrow">Inspecting task ${num(g.selected+1)}</span><h4>${selected.title}</h4><dl><dt>What it needs</dt><dd>${selected.inputs}</dd><dt>What it should produce</dt><dd>${selected.output}</dd><dt>What to check</dt><dd>${selected.check}</dd><dt>When to stop</dt><dd>${selected.stop}</dd></dl><p class="small muted">Inspecting a task does not complete it. Use the walkthrough controls to advance the example.</p></aside></div><div class="simulation-note">${icon('info')} All responses in this example are prewritten. No AI runs, documents are retrieved, or messages are sent.</div>${field('graph-lesson','What would you change in a similar assignment?','Identify a task or review point that would help you notice missing evidence before drafting a recommendation.')}${widgetNote('This is a fictional teaching demonstration. Evidence variations and responses are prepared examples. The diagram does not implement permissions in another application.')}</div>`;
}

function processText(){const keys=['outcome','steps','friction','remove','actor','controls','pilot','measure','version'];const titles=['Define the outcome','Map the current work','Find friction and failure','Remove before adding','Assign the best actor','Build controls','Pilot narrowly','Measure the whole result','Revise and version'];return 'PROCESS IMPROVEMENT BRIEF\n\n'+keys.map((k,i)=>`${i+1}. ${titles[i]}\n${String(value(`process-${k}`)).trim()||'[To be completed.]'}`).join('\n\n');}
function updateProcess(){const el=document.getElementById('process-map');if(!el)return;const lines=String(value('process-steps')).split('\n').map(s=>s.trim()).filter(Boolean).slice(0,30);el.innerHTML=lines.length?lines.map((l,i)=>`${i?'<b aria-hidden="true">→</b>':''}<span>${esc(l)}</span>`).join(''):'<span>Write one current step per line to see your sequence.</span>';}
function updateShipping(){const el=document.getElementById('shipping-result');if(!el)return;const count=SHIPPING.filter((_,i)=>value(`shipping-${i}`)===true&&String(value(`shipping-evidence-${i}`)).trim()).length;el.className='status-box '+(count===6?'':'warn');el.innerHTML=count===6?'<strong>All six areas have a checked box and a note.</strong><p>The worksheet records your assessment, not a certification. The responsible reviewer still needs to examine the evidence and decide whether a pilot is appropriate.</p>':`<strong>${count} of 6 areas have both a check and an evidence note.</strong><p>Record the test, source, reviewer, or remaining work in each area. The responsible reviewer needs evidence of what was checked, not just a completed form.</p>`;}
function reflectionFields(){const [gi,qi]=String(value('reflection-select')||'0-0').split('-').map(Number);const group=REFLECTIONS[gi]||REFLECTIONS[0];const index=Number.isInteger(qi)&&qi>=0&&qi<group.questions.length?qi:0;const question=group.questions[index];return `<div class="comparison-note"><strong>${esc(question)}</strong><div class="small muted" style="margin-top:8px">${group.source}</div></div>${[['start','My initial view'],['mid','After relevant experience'],['end','A later reflection']].map(([period,t])=>field(`reflection-${Number.isInteger(gi)?gi:0}-${index}-${period}`,t,'What do you think? What experience or evidence shaped your view?')).join('')}`;}
function onWidgetInput(key,el){if(key.startsWith('preflight-'))updatePreflight();if(key.startsWith('prompt-'))updatePrompt();if(key.startsWith('order-'))updateOrder();if(key.startsWith('process-'))updateProcess();if(key.startsWith('shipping-'))updateShipping();if(key==='reflection-select'){const area=document.getElementById('reflection-fields');if(area){area.innerHTML=reflectionFields();restoreFields();}}}
function handleWidgetAction(action,el){
 if(action==='method-step'){methodIndex=Number(el.dataset.step);refreshWidget('method');document.querySelector(`[data-action=method-step][data-step="${methodIndex}"]`)?.focus({preventScroll:true});}
 else if(action==='timer-toggle'){if(pauseClock.running){pauseClock.remaining=Math.max(0,Math.ceil((pauseClock.deadline-Date.now())/1000));pauseClock.running=false;}else{if(!pauseClock.remaining)pauseClock.remaining=240;pauseClock.deadline=Date.now()+pauseClock.remaining*1000;pauseClock.running=true;}refreshWidget('pause','timer-toggle');}
 else if(action==='timer-reset'){pauseClock={remaining:240,running:false,deadline:0};refreshWidget('pause','timer-reset');}
 else if(action==='pause-save'){if([0,1,2,3,4].some(i=>!String(value(`pause-${i}`)).trim())){toast('Write an answer to each of the five questions first.');return true;}if(value('pause-baseline')&&!confirm('Replace the assessment saved for comparison with your current five answers? The previous comparison copy will be replaced.'))return true;setField('pause-baseline',['What is my current answer?','What is the strongest part?','What is the weakest part?','What still needs checking?','What feedback would help?'].map((q,i)=>`${q}\n${value(`pause-${i}`)}`).join('\n\n'));refreshWidget('pause','pause-save');toast('Your assessment is saved for comparison. Return after receiving feedback elsewhere.');}
 else if(action==='prompt-preset'){if(PROMPT_KEYS.some(k=>String(value(`prompt-${k}`)).trim())&&!confirm('Load this example in place of the current prompt fields? Download the current prompt first to keep it. Other saved work will not change.'))return true;Object.entries(PROMPT_PRESETS[el.dataset.preset]).forEach(([k,v])=>state.fields[`prompt-${k}`]=v);saveState();refreshWidget('promptbuilder');toast('Example loaded. Adapt it before use.');}
 else if(action==='save-built-prompt'){if(!String(value('prompt-task')).trim()){toast('Define the task before saving a prompt.');return true;}if(value('prompt-saved-assignment')&&!confirm('Replace the separately saved prompt version? Download it first to keep more than one version.'))return true;setField('prompt-saved-assignment',builtPrompt());toast('This prompt version is saved in My saved work.');}
 else if(action==='download-built-prompt')downloadFile('my-ai-assignment.txt',builtPrompt());
 else if(action==='order-preset'){if(ORDER_FIELDS.some(([k])=>String(value(`order-${k}`)).trim())&&!confirm('Replace the current work-order fields with the fictional vendor example?'))return true;Object.entries(ORDER_PRESET).forEach(([k,v])=>state.fields[`order-${k}`]=v);saveState();refreshWidget('workorder');toast('Vendor example loaded. Check every field for your own use.');}
 else if(action==='copy-order')copyText(orderText());
 else if(action==='download-order')downloadFile('agent-work-order.txt',orderText());
 else if(action==='fee-open'){if(!String(value('fee-draft')).trim()&&!String(value('fee-choice')).trim()){toast('Write a revision or describe your proposed changes before opening the alternatives.');document.querySelector('[data-save=fee-draft]')?.focus();return true;}setField('fee-open',true);refreshWidget('fee','fee-open');}
 else if(action==='fee-option'){setField('fee-choice',el.dataset.step);refreshWidget('fee');document.querySelector(`[data-action=fee-option][data-step="${el.dataset.step}"]`)?.focus({preventScroll:true});}
 else if(action==='reveal-case'){const id=el.dataset.case;if(!String(value(`${id}-draft`)).trim()){toast('Write your first revision or a note about the changes you would make.');document.querySelector(`[data-save="${id}-draft"]`)?.focus();return true;}setField(`${id}-revealed`,true);refreshWidget(id,'reveal-case');}
 else if(action==='aiism-lens'){aiismIndex=Number(el.dataset.step);refreshWidget('aiisms');document.querySelector(`[data-action=aiism-lens][data-step="${aiismIndex}"]`)?.focus({preventScroll:true});}
 else if(action==='graph-mode'){graphState={step:-1,selected:0,mode:el.dataset.mode,resolution:'',evidence:el.dataset.mode==='complete',updated:false};refreshWidget('graph');}
 else if(action==='graph-node'){graphState.selected=Number(el.dataset.step);refreshWidget('graph');if(window.innerWidth<=1150){const panel=document.querySelector('.graph-detail');panel?.focus({preventScroll:true});panel?.scrollIntoView({block:'start',behavior:'instant'});}else document.querySelector(`[data-action=graph-node][data-step="${graphState.selected}"]`)?.focus({preventScroll:true});}
 else if(action==='graph-back'){const task=document.querySelector(`[data-action=graph-node][data-step="${graphState.selected}"]`);task?.focus({preventScroll:true});task?.scrollIntoView({block:'center',behavior:'instant'});}
 else if(action==='graph-reset'){graphState={step:-1,selected:0,mode:graphState.mode,resolution:'',evidence:graphState.mode==='complete',updated:false};refreshWidget('graph','graph-next');}
 else if(action==='graph-next'){const g=graphState;if(g.step===3&&g.mode==='missing'&&!g.evidence&&!g.resolution)return true;g.step=g.step<0?0:g.step===0?2:Math.min(g.step+1,7);g.selected=g.step;refreshWidget('graph',g.step===3&&g.mode==='missing'&&!g.evidence&&!g.resolution?'graph-evidence':'graph-next');}
 else if(action==='graph-evidence'){graphState.evidence=true;graphState.resolution='evidence';graphState.updated=true;graphState.step=2;graphState.selected=2;refreshWidget('graph','graph-next');}
 else if(action==='graph-qualify'){graphState.resolution='qualified';graphState.selected=4;refreshWidget('graph','graph-next');}
 else if(action==='copy-process')copyText(processText());
 else if(action==='download-process')downloadFile('process-improvement-brief.txt',processText());
 else if(action==='export-playbook'){const text='MY AI LAWYERING PLAYBOOK\n\n'+PLAYBOOK_FIELDS.map(([k,t,h])=>`${t}\n${String(value(`playbook-${k}`)).trim()||'[No entry yet.]'}`).join('\n\n');downloadFile('my-ai-lawyering-playbook.txt',text,'text/plain');}
 else return false;
 return true;
}
const previousWidgetHandler=handleWidgetAction;
handleWidgetAction=function(action,el){if(action==='priorities-reveal'){if(!String(value('priorities-reason')).trim()){toast('Write why you chose those priorities before opening the discussion.');document.querySelector('[data-save=priorities-reason]')?.focus();return true;}setField('priorities-reveal',true);refreshWidget('priorities','priorities-reveal');return true;}return previousWidgetHandler(action,el);};

